#include "DemoManager.h"
#include <fstream>
#include <iostream>
#include <sstream>
DemoManager::DemoManager():nextId(1001){} Resource* DemoManager::findResource(const std::string&id){for(auto&r:resources)if(r.getId()==id)return &r;return nullptr;} bool DemoManager::loadResources(const std::string&f){std::ifstream in(f);if(!in){std::cerr<<"Error opening "<<f<<'\n';return false;}std::string line;while(std::getline(in,line)){if(line.empty())continue;std::stringstream ss(line);std::string id,name;std::getline(ss,id,'|');std::getline(ss,name,'|');resources.emplace_back(id,name);}return true;} void DemoManager::showResources()const{std::cout<<"\n--- Resources ---\n";for(const auto&r:resources)r.display();} void DemoManager::createReservation(){std::string student,rid,date;std::cout<<"Student name: ";std::getline(std::cin>>std::ws,student);std::cout<<"Resource ID: ";std::getline(std::cin,rid);Resource*r=findResource(rid);if(!r){std::cout<<"Invalid resource ID.\n";return;}if(!r->isAvailable()){std::cout<<"Resource unavailable. Added to waiting list.\n";waiting.add(student,rid);return;}std::cout<<"Reservation date: ";std::getline(std::cin,date);Reservation x(nextId++,student,rid,date);reservations.insert(x);r->setAvailable(false);std::cout<<"Reservation created successfully.\n";x.display();} void DemoManager::cancelReservation(){int id;std::cout<<"Reservation ID: ";std::cin>>id;Reservation x(0,"","","");if(!reservations.remove(id,x)){std::cout<<"Reservation not found.\n";return;}Resource*r=findResource(x.getResourceId());if(r)r->setAvailable(true);cancelled.push(x);std::cout<<"Reservation cancelled and added to cancellation history.\n";if(!waiting.empty()&&r){WaitRequest w;waiting.pop(w);Reservation y(nextId++,w.student,w.resourceId,x.getDate());reservations.insert(y);r->setAvailable(false);std::cout<<"Resource automatically assigned to next waiting student:\n";y.display();}} void DemoManager::showReservations()const{std::cout<<"\n--- Active Reservations ---\n";reservations.display();} void DemoManager::showWaiting()const{std::cout<<"\n--- Waiting List ---\n";waiting.display();} void DemoManager::undo(){Reservation x(0,"","","");if(!cancelled.pop(x)){std::cout<<"Nothing to undo.\n";return;}Resource*r=findResource(x.getResourceId());if(!r||!r->isAvailable()){std::cout<<"Cannot restore: resource is currently unavailable.\n";cancelled.push(x);return;}reservations.insert(x);r->setAvailable(false);std::cout<<"Most recent cancellation restored:\n";x.display();}
